-- Suppressors: 'toy helicopter' should not resolve to ch88.
INSERT INTO category_keywords (category_id, hs_chapter, keyword, weight, signal_class, source, notes)
SELECT cc.id, v.hs, v.kw, v.wt, v.cls, 'manual', v.note
FROM   classification_categories cc, (VALUES
    -- anchors
    ('88', 'commercial aircraft',1.0, 'anchor',     'CCTR-007 ch88 anchor'),
    ('88', 'turbojet engine',    1.0, 'anchor',     'CCTR-007 ch88 anchor — aviation propulsion'),
    ('88', 'turbofan',           1.0, 'anchor',     'CCTR-007 ch88 anchor'),
    ('88', 'fuselage',           1.0, 'anchor',     'CCTR-007 ch88 anchor — aircraft structure'),
    ('88', 'avionics',           1.0, 'anchor',     'CCTR-007 ch88 anchor'),
    ('88', 'rotorcraft',         1.0, 'anchor',     'CCTR-007 ch88 anchor — helicopter family'),
    ('88', 'spacecraft',         1.0, 'anchor',     'CCTR-007 ch88 anchor'),
    -- suppressors
    ('88', 'toy',                0.9, 'suppressor', 'CCTR-008 toy helicopter is not aircraft'),
    ('88', 'rc',                 0.7, 'suppressor', 'CCTR-008 RC helicopter is hobby ch95'),
    ('88', 'scale model',        0.9, 'suppressor', 'CCTR-008 model aircraft is hobby ch95')
) AS v(hs, kw, wt, cls, note)
WHERE cc.name = 'machinery'
ON CONFLICT (category_id, hs_chapter, keyword, signal_class) WHERE hs_chapter IS NOT NULL DO NOTHING;


