    ('28', 'nitric acid',        1.0, 'anchor',     'CCTR-009 ch28 anchor'),
    ('28', 'ammonia',            0.9, 'anchor',     'CCTR-009 ch28 anchor'),
    ('28', 'chlorine gas',       1.0, 'anchor',     'CCTR-009 ch28 anchor'),
    -- ch29 — organic
    ('29', 'methanol',           1.0, 'anchor',     'CCTR-010 ch29 anchor — organic alcohol'),
    ('29', 'ethanol industrial', 1.0, 'anchor',     'CCTR-010 ch29 anchor — denatured ethanol'),
    ('29', 'acetone',            1.0, 'anchor',     'CCTR-010 ch29 anchor'),
    ('29', 'toluene',            1.0, 'anchor',     'CCTR-010 ch29 anchor'),
