-- ── ch30 — pharmaceuticals ───────────────────────────────────────────────────
-- Anchors for drug-product nouns that should beat the chemicals/cosmetics tail.
INSERT INTO category_keywords (category_id, hs_chapter, keyword, weight, signal_class, source, notes)
SELECT cc.id, v.hs, v.kw, v.wt, v.cls, 'manual', v.note
FROM   classification_categories cc, (VALUES
    ('30', 'vaccine',            1.0, 'anchor',     'CCTR-011 ch30 anchor — biologic'),
    ('30', 'insulin',            1.0, 'anchor',     'CCTR-011 ch30 anchor — biologic'),
    ('30', 'antibiotic',         1.0, 'anchor',     'CCTR-011 ch30 anchor'),
    ('30', 'tablet',             0.7, 'anchor',     'CCTR-011 ch30 anchor — dosage form'),
    ('30', 'capsule',            0.7, 'anchor',     'CCTR-011 ch30 anchor — dosage form'),
    ('30', 'sterile injection',  1.0, 'anchor',     'CCTR-011 ch30 anchor'),
    ('30', 'api pharmaceutical', 1.0, 'anchor',     'CCTR-011 ch30 anchor — active ingredient'),
    ('30', 'syringe sterile',    0.95,'anchor',     'CCTR-011 ch30 anchor — sterile medical device'),
    -- suppressor: cosmetics overlap
    ('30', 'cosmetic',           0.7, 'suppressor', 'CCTR-012 cosmetic claim suppresses drug ch30')
) AS v(hs, kw, wt, cls, note)
WHERE cc.name = 'pharmaceuticals'
ON CONFLICT (category_id, hs_chapter, keyword, signal_class) WHERE hs_chapter IS NOT NULL DO NOTHING;


-- ── ch09 — coffee, tea, mate, spices (food_beverages) ────────────────────────
-- Single most impactful anchor set: 'tea' anchored in ch09 fixes the
-- "Tea, bags" → electronics regression (SID 50) and prevents 'tea' from
-- ever scoring electronics through 'bag' keyword overlap.
INSERT INTO category_keywords (category_id, hs_chapter, keyword, weight, signal_class, source, notes)
SELECT cc.id, v.hs, v.kw, v.wt, v.cls, 'manual', v.note
FROM   classification_categories cc, (VALUES
    ('09', 'tea',                1.0, 'anchor',     'CCTR-013 ch09 anchor — fixes "Tea, bags" → electronics regression'),
    ('09', 'tea bags',           1.0, 'anchor',     'CCTR-013 ch09 anchor — phrase match'),
    ('09', 'green tea',          1.0, 'anchor',     'CCTR-013 ch09 anchor'),
    ('09', 'black tea',          1.0, 'anchor',     'CCTR-013 ch09 anchor'),
    ('09', 'coffee',             1.0, 'anchor',     'CCTR-013 ch09 anchor'),
    ('09', 'coffee beans',       1.0, 'anchor',     'CCTR-013 ch09 anchor'),
    ('09', 'cardamom',           1.0, 'anchor',     'CCTR-013 ch09 anchor — spice'),
    ('09', 'turmeric',           1.0, 'anchor',     'CCTR-013 ch09 anchor — spice'),
    ('09', 'cinnamon',           1.0, 'anchor',     'CCTR-013 ch09 anchor — spice'),
    ('09', 'black pepper',       1.0, 'anchor',     'CCTR-013 ch09 anchor — spice')
) AS v(hs, kw, wt, cls, note)
WHERE cc.name = 'food_beverages'
ON CONFLICT (category_id, hs_chapter, keyword, signal_class) WHERE hs_chapter IS NOT NULL DO NOTHING;


-- ── ch85 — electronics: lithium-ion anchor + toy battery suppressor ──────────
-- The plan's headline polysemy fix: 'battery' alone is a signal across many
-- chapters, but 'lithium-ion battery' is a real-electronics anchor. The
-- toy-side handles the inverse via the 'toy' modifier in ch95.
INSERT INTO category_keywords (category_id, hs_chapter, keyword, weight, signal_class, source, notes)
SELECT cc.id, v.hs, v.kw, v.wt, v.cls, 'manual', v.note
FROM   classification_categories cc, (VALUES
    ('85', 'lithium-ion battery',1.0, 'anchor',     'CCTR-014 ch85 anchor — real-electronics battery'),
    ('85', 'lithium ion battery',1.0, 'anchor',     'CCTR-014 ch85 anchor — alternate spelling'),
    ('85', 'li-ion cell',        1.0, 'anchor',     'CCTR-014 ch85 anchor'),
    ('85', 'pcb assembly',       1.0, 'anchor',     'CCTR-014 ch85 anchor — printed circuit'),
    ('85', 'semiconductor wafer',1.0, 'anchor',     'CCTR-014 ch85 anchor'),
    ('85', 'integrated circuit', 1.0, 'anchor',     'CCTR-014 ch85 anchor'),
    -- suppressors: toy-battery, AAA-pack should NOT swamp ch85 when toy modifier fires
    ('85', 'toy',                0.7, 'suppressor', 'CCTR-015 toy modifier suppresses ch85 battery'),
    ('85', 'plush',              0.6, 'suppressor', 'CCTR-015 plush-toy battery is hobby ch95'),
    -- modifier on the chemicals/cosmetics overlap: 'industrial-grade' affirms ch85
    ('85', 'industrial-grade',   0.7, 'modifier',   'targets:ch85 — affirms electronics for industrial battery shipments')
) AS v(hs, kw, wt, cls, note)
WHERE cc.name = 'electronics'
ON CONFLICT (category_id, hs_chapter, keyword, signal_class) WHERE hs_chapter IS NOT NULL DO NOTHING;
